import { Description } from "./Description";
import { Base, typeCast, Type, markType } from "./type";

/**
 * @hidden 
 */
export class RectDescription extends Description {
	static $t: Type = markType(RectDescription, 'RectDescription', (<any>Description).$);
	private _left: number = 0;
	get left(): number {
		return this._left;
	}
	set left(a: number) {
		this._left = a;
	}
	private _top: number = 0;
	get top(): number {
		return this._top;
	}
	set top(a: number) {
		this._top = a;
	}
	private _width: number = 0;
	get width(): number {
		return this._width;
	}
	set width(a: number) {
		this._width = a;
	}
	private _height: number = 0;
	get height(): number {
		return this._height;
	}
	set height(a: number) {
		this._height = a;
	}
	equals(a: any): boolean {
		if (a == null || !(typeCast<RectDescription>((<any>RectDescription).$, a) !== null)) {
			return super.equals(a);
		}
		let b = <RectDescription>a;
		return this.left == b.left && this.top == b.top && this.width == b.width && this.height == b.height;
	}
}


