import { Description } from "./Description";
import { Base, typeCast, Type, markType } from "./type";

/**
 * @hidden 
 */
export class PointDescription extends Description {
	static $t: Type = markType(PointDescription, 'PointDescription', (<any>Description).$);
	private _x: number = 0;
	get x(): number {
		return this._x;
	}
	set x(a: number) {
		this._x = a;
	}
	private _y: number = 0;
	get y(): number {
		return this._y;
	}
	set y(a: number) {
		this._y = a;
	}
	equals(a: any): boolean {
		if (a == null || !(typeCast<PointDescription>((<any>PointDescription).$, a) !== null)) {
			return super.equals(a);
		}
		let b = <PointDescription>a;
		return this.x == b.x && this.y == b.y;
	}
}


