import { Description } from "./Description";
import { Base, typeCast, Type, markType } from "./type";

/**
 * @hidden 
 */
export class SizeDescription extends Description {
	static $t: Type = markType(SizeDescription, 'SizeDescription', (<any>Description).$);
	private _width: number = 0;
	get width(): number {
		return this._width;
	}
	set width(a: number) {
		this._width = a;
	}
	private _height: number = 0;
	get height(): number {
		return this._height;
	}
	set height(a: number) {
		this._height = a;
	}
	equals(a: any): boolean {
		if (a == null || !(typeCast<SizeDescription>((<any>SizeDescription).$, a) !== null)) {
			return super.equals(a);
		}
		let b = <SizeDescription>a;
		return this.width == b.width && this.height == b.height;
	}
}


